function mediaUrl(v){const raw=String(v||'').trim();if(!raw)return '';if(/^data:image\/(?:png|jpe?g|webp|gif);base64,/i.test(raw))return raw;try{const u=new URL(raw,location.origin);return ['http:','https:'].includes(u.protocol)?u.href:''}catch(_){return ''}}
