function optionCard(section,o){const selected=isSelected(section,o),img=mediaUrl(o.image),interactive=canInteract();return '<article class="pc-option '+(selected?'selected':'')+' '+(!interactive?'readonly':'')+'" data-option-card="'+esc(o.id)+'">'+(img?'<div class="pc-option-image"><img src="'+esc(img)+'" alt="'+esc(o.title||'Pool option')+'"></div>':'')+'<div class="pc-option-body"><div class="pc-option-badge">'+esc(o.recommended?'POOL BROS RECOMMENDED':o.badge||'')+'</div><h3>'+esc(o.title)+'</h3><p>'+esc(o.description||o.subtitle||'')+'</p><div class="pc-option-benefits">'+(o.benefits||[]).map(b=>'<span>'+esc(b)+'</span>').join('')+'</div><div class="pc-option-foot"><div class="pc-option-price"><small>'+((section.priceMode==='included')?'Specification':'Your option')+'</small><strong>'+esc(optionPrice(section,o)||'Specified')+'</strong></div>'+(section.rule==='locked'?'<span class="pc-readonly-choice">Included</span>':interactive?'<button class="pc-select" data-select-option="'+esc(o.id)+'" data-section="'+esc(section.id)+'">'+(selected?'Selected':'Select')+'</button>':'<span class="pc-readonly-choice">'+(selected?'Selected specification':'View only')+'</span>')+'</div>'+(section.questions&&interactive?'<button class="pc-question-link" data-question data-section="'+esc(section.id)+'" data-option="'+esc(o.id)+'">Ask a question about this option</button>':'')+'</div></article>'}
