function milestoneHtml(i){const saved=proposal.investment?.paymentPlan||proposal.investment?.paymentMilestones||[];let rows=[];if(saved.length){let remaining=i.gross;saved.forEach((m,idx)=>{let amount=0;if(m.type==='fixed')amount=Math.min(remaining,Number(m.value??m.amount??0));else if(m.type==='balance')amount=Math.max(0,remaining);else if(m.type==='percent')amount=i.gross*Number(m.value??m.percent??0)/100;else amount=Number(m.amount||0)*(i.gross/Math.max(.01,Number(proposal.investment?.gross||i.gross||1)));amount=Math.max(0,Math.min(remaining,amount));remaining-=amount;rows.push({label:m.label,percent:i.gross>0?Math.round(amount/i.gross*1000)/10:0,amount,requestOnAcceptance:!!m.requestOnAcceptance})});if(remaining>.01&&rows.length)rows[rows.length-1].amount+=remaining}else rows=[{label:'Secure project',percent:proposal.depositPercent||50,amount:i.deposit,requestOnAcceptance:true}];return rows.map((m,idx)=>'<div class="pc-milestone"><div><b>'+esc((m.percent!=null?m.percent+'% · ':'')+m.label)+'</b><span>'+((m.requestOnAcceptance||idx===0)&&proposal.payment?.mode!=='none'?'Requested after acceptance':'As agreed in this proposal')+'</span></div><strong>'+cash(m.amount)+'</strong></div>').join('')}
